head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

//발행기관  정보 조회 하는 팝업 
scwin.vScrenID = "ULDINS93700.xml";
scwin.param1 = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
/********************************************** 
 * 함수명   : ins_search
 * 설명       : 발행기관 각 코드를 조회한다.
 ***********************************************/
scwin.ins_search = function() {
    var queryId = "";
    // 신청자 정보 조회 하는 
    // param1 => STD_CD_APPL_ID , ISUR_APPL_ID
    if (scwin.param1 == "GOVBND_ISUR_CD") {
        // 국채발행체코드
        queryId = "lds.ins.corpinfo.select.listGovbndIsurCdInquiry";
    } else if (scwin.param1 == "MUNIBND_ISUR_CD") {
        // 지방채발행체코드
        queryId = "lds.ins.corpinfo.select.listNunibndIsurCdInquiry";
    } else if (scwin.param1 == "SPECLBND_ISUR_CD") {
        // 특수채발행체코드
        queryId = "lds.ins.corpinfo.select.listSpeclbndIsurCdInquiry";
    } else if (scwin.param1 == "BENFCERT_ISUR_CD") {
        // 수익증권발행체코드
        queryId = "lds.ins.corpinfo.select.listBencertbndIsurCdInquiry";
    } else if (scwin.param1 == "WRNT_ISUR_CD") {
        // 파생상품발행기관정보
        queryId = "lds.ins.corpinfo.select.listWrntIsurCdInquiry";
    }


    //alert(queryId); 
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=STDCDTEMP_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=" + queryId;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};
scwin.gform_onload = function() {
    $c.stf.showObj(txb_TITLE, false);
    var arrPar = new Array();
    var parentWin = $c.frame.path("../");
    var fn_GetPar = parentWin.fn_GetParam;
    if (fn_GetPar != undefined) {
        fn_GetPar(arrPar);
        scwin.param1 = ((arrPar.length >= 1) && (arrPar[0] != undefined) ? arrPar[0] : "");
        //  param2  = ((arrPar.length >= 1) && (arrPar[1] != undefined) ? arrPar[1] : "");


        if (scwin.param1 == "GOVBND_ISUR_CD") {
            // 국채발행체코드 
            $c.stf.setObjectValue(txb_TITLE, "※ 국채기관코드");
            $c.cm.setColumnProp(grd_Grid, "C", "Name", "국채;기관코드");
            $c.cm.setColumnProp(grd_Grid, "E", "Show", false);
            $c.cm.setColumnProp(grd_Grid, "F", "Show", false);
            $c.cm.setColumnProp(grd_Grid, "A", "width", "100");
            $c.cm.setColumnProp(grd_Grid, "B", "width", "270");
            $c.cm.setColumnProp(grd_Grid, "C", "width", "100");
        } else if (scwin.param1 == "MUNIBND_ISUR_CD") {
            // 지방채발행체코드 
            $c.stf.setObjectValue(txb_TITLE, "※ 지방채기관코드");
            $c.cm.setColumnProp(grd_Grid, "C", "Name", "지방채;기관코드");
            $c.cm.setColumnProp(grd_Grid, "E", "Show", false);
            $c.cm.setColumnProp(grd_Grid, "F", "Show", false);
            $c.cm.setColumnProp(grd_Grid, "A", "width", "100");
            $c.cm.setColumnProp(grd_Grid, "B", "width", "270");
            $c.cm.setColumnProp(grd_Grid, "C", "width", "100");
        } else if (scwin.param1 == "SPECLBND_ISUR_CD") {
            // 특수채발행체코드 
            $c.stf.setObjectValue(txb_TITLE, "※ 특수채기관코드");
            $c.cm.setColumnProp(grd_Grid, "C", "Name", "특수채;기관코드");
            $c.cm.setColumnProp(grd_Grid, "E", "Show", false);
            $c.cm.setColumnProp(grd_Grid, "F", "Show", false);
            $c.cm.setColumnProp(grd_Grid, "A", "width", "100");
            $c.cm.setColumnProp(grd_Grid, "B", "width", "270");
            $c.cm.setColumnProp(grd_Grid, "C", "width", "100");
        } else if (scwin.param1 == "BENFCERT_ISUR_CD") {
            // 수익증권발행체코드 
            $c.stf.setObjectValue(txb_TITLE, "※ 수익증권기관코드");
            $c.cm.setColumnProp(grd_Grid, "C", "Name", "수익증권;기관코드");
            $c.cm.setColumnProp(grd_Grid, "E", "Show", false);
            $c.cm.setColumnProp(grd_Grid, "F", "Show", false);
            $c.cm.setColumnProp(grd_Grid, "A", "width", "100");
            $c.cm.setColumnProp(grd_Grid, "B", "width", "270");
            $c.cm.setColumnProp(grd_Grid, "C", "width", "100");
        } else if (scwin.param1 == "WRNT_ISUR_CD") {
            // 파생상품발행기관정보 
            $c.stf.setObjectValue(txb_content, "목록에 없는 발행기관은 파생상품발행기관관리에서 파생상품기관코드를 신규등록하세요.");
            $c.stf.setObjectValue(txb_TITLE, "※ 파생상품발행기관코드");
            $c.cm.setColumnProp(grd_Grid, "C", "Name", "파생상품;발행기관코드;(ETN/ELW)");
        }
        scwin.ins_search();
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
};
